<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { NModal } from 'naive-ui';
const props=defineProps<{show:boolean}>();
const emit=defineEmits<{'update:show':[boolean]}>();
interface Config {auto_research:boolean;observation_days:number;min_samples:number;max_drawdown_bps:number;min_return_bps:number;initial_cash:string;max_active:number;stock_count:number;commission_bps:number;min_commission:string;stamp_tax_bps:number;transfer_fee_bps:number;slippage_bps:number}
interface Metrics {total_return_bps:number;max_drawdown_bps:number;sample_count:number;win_rate_bps:number;benchmark_return_bps:number|null;equity:string}
interface Experiment {id:number;version_id:number;name:string;hypothesis:string;rule:string;state:string;account_id:number|null;created_at:string;last_message:string;selection_json:string;filter:Record<string,unknown>;config:Config;remaining_days:number;remaining_samples:number;elapsed_days:number;verdict:string;detail:null|{metrics:Metrics;targets:Array<{symbol:string;name:string}>;orders:Array<{id:number;signal_date:string;symbol:string;side:string;quantity:number;status:string;reject_reason:string|null}>};curve:Array<{date:string;equity:string;return_bps:number;drawdown_bps:number}>}
interface Dashboard {config:Config;experiments:Experiment[];local_ready:boolean;agent_installed:boolean;last_auto_message:string;busy:boolean}
const dashboard=ref<Dashboard|null>(null);const selectedId=ref<number|null>(null);const tab=ref('experiments');const busy=ref('');const error=ref('');const notice=ref('');
const settings=reactive<Config>({auto_research:false,observation_days:28,min_samples:20,max_drawdown_bps:1500,min_return_bps:0,initial_cash:'1000000000',max_active:3,stock_count:5,commission_bps:3,min_commission:'50000',stamp_tax_bps:5,transfer_fee_bps:1,slippage_bps:5});
const cashYuan=ref(100000);const minFee=ref(5);const drawdownPct=ref(15);const returnPct=ref(0);
const workspace=ref<{path:string;skills:string[];prompt:string}|null>(null);
const selected=computed(()=>dashboard.value?.experiments.find(e=>e.id===selectedId.value)??null);
interface LiveInfo {engine:string;message:string;updated_at:string|null;plans:Array<{symbol:string;buy_low:number;buy_high:number;stop:number;take:number;basis_date:string}>;executions:unknown[];marks:number}
const live=computed(()=>(selected.value as (Experiment&{live?:LiveInfo})|null)?.live);
const daily=computed(()=>(selected.value as (Experiment&{daily_comparison?:Experiment['detail']})|null)?.daily_comparison);
const executionMode=ref('realtime');
const states:Record<string,string>={candidate:'待启动',observing:'前向验证',extended:'延长观察',qualified:'待采纳',adopted:'持续跟踪',paused:'已暂停',rejected:'已淘汰'};
const rules:Record<string,string>={trend_follow:'趋势回踩',mean_reversion:'均值回归',breakout:'放量突破'};
const pct=(n:number|null|undefined)=>n==null?'—':`${(n/100).toFixed(2)}%`;
const money=(n:string)=> (Number(n)/10000).toLocaleString('zh-CN',{maximumFractionDigits:2});
const counts=computed(()=>({all:dashboard.value?.experiments.length??0,running:dashboard.value?.experiments.filter(e=>['observing','extended','adopted'].includes(e.state)).length??0,rejected:dashboard.value?.experiments.filter(e=>e.state==='rejected').length??0}));
let timer:ReturnType<typeof setInterval>|undefined;let request=0;
async function load(reset=false){const req=++request;try{const result=await invoke<Dashboard>('research_dashboard');if(req!==request)return;dashboard.value=result;if(reset){Object.assign(settings,result.config);executionMode.value=(result.config as Config&{execution_mode?:string}).execution_mode??'realtime';cashYuan.value=Number(settings.initial_cash)/10000;minFee.value=Number(settings.min_commission)/10000;drawdownPct.value=settings.max_drawdown_bps/100;returnPct.value=settings.min_return_bps/100;}if(!selectedId.value&&result.experiments.length)selectedId.value=result.experiments[0].id;}catch(e){if(req===request)error.value=String(e);}}
watch(()=>props.show,open=>{if(timer)clearInterval(timer);if(open){void load(true);timer=setInterval(()=>void load(),5000);}}, {immediate:true});
onBeforeUnmount(()=>{++request;if(timer)clearInterval(timer);});
async function act(key:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=key;error.value='';notice.value='';try{await fn();await load();}catch(e){error.value=String(e);await load();}finally{busy.value='';}}
function discover(){void act('discover',async()=>{selectedId.value=await invoke<number>('research_discover');tab.value='experiments';notice.value='候选已登记，查看假设和冻结条件后启动验证。';});}
function start(){const id=selected.value?.id;if(!id)return;void act('start',async()=>{await invoke('research_start',{experimentId:id});notice.value='已自动选股并创建隔离模拟账户；按冻结的实时 / 日线 / 并行模式独立推进。';});}
function action(action:string){const id=selected.value?.id;if(!id)return;void act(action,async()=>{await invoke('research_action',{experimentId:id,action});});}
function save(){void act('save',async()=>{const config={...settings,execution_mode:executionMode.value,initial_cash:String(Math.round(cashYuan.value*10000)),min_commission:String(Math.round(minFee.value*10000)),max_drawdown_bps:Math.round(drawdownPct.value*100),min_return_bps:Math.round(returnPct.value*100)};await invoke('save_research_config',{config});notice.value='已保存。阈值与费用只应用到新候选；已有实验保持冻结。';});}
function openClaude(){void act('claude',async()=>{workspace.value=await invoke('open_research_claude');notice.value='已请求打开 Claude 交互窗口。在窗口中选择你的 Skill，完成后回此处导入候选。';});}
function inspectWorkspace(){void act('workspace',async()=>{workspace.value=await invoke('research_workspace');});}
function importCandidate(){void act('import',async()=>{selectedId.value=await invoke<number>('import_research_candidate');tab.value='experiments';notice.value='candidate.json 已校验并登记，未自动成交。';});}
const chart=computed(()=>{const rows=selected.value?.curve??[];const values=[0,...rows.map(p=>p.return_bps)];const low=Math.min(0,...values),high=Math.max(100,...values),range=high-low||1;const points=values.map((v,i)=>`${40+i/(Math.max(values.length-1,1))*650},${150-(v-low)/range*115}`).join(' ');return{points,low,high,zero:150-(0-low)/range*115};});
const stages=['研究假设','冻结选股','模拟执行','考核评估','采纳跟踪'];
const stage=computed(()=>!selected.value?0:selected.value.account_id==null?1:['qualified','adopted','rejected'].includes(selected.value.state)?4:3);
</script>

<template>
<NModal :show="show" @update:show="emit('update:show',$event)" preset="card" title="研究中心" class="research-modal" :style="{width:'min(1180px,96vw)',maxHeight:'94vh',overflow:'auto'}" :bordered="false">
  <div class="research-center">
    <header class="hero"><div><span class="eyebrow">RESEARCH → EVIDENCE</span><h2>让每一个策略，接受时间的检验</h2><p>提出假设，冻结规则，用独立模拟账户积累证据。收益、回撤与基准共同决定下一步。</p></div><div class="hero-stats"><span><b>{{counts.all}}</b>已登记</span><span><b>{{counts.running}}</b>验证中</span><span><b>{{counts.rejected}}</b>已淘汰</span></div></header>
    <div class="steps"><span v-for="(name,i) in stages" :key="name" :class="{done:i<stage}"><b>{{String(i+1).padStart(2,'0')}}</b>{{name}}</span></div>
    <div class="health"><span :class="{good:dashboard?.agent_installed}">{{dashboard?.agent_installed?'● Claude 已检测':'○ Claude 未检测'}}</span><span :class="{good:dashboard?.local_ready}">{{dashboard?.local_ready?'● 本地历史已启用':'○ 请先启用本地历史'}}</span><span>{{dashboard?.config.auto_research?'自动研究已开启 · 交易日盘后最多一次':'自动研究关闭 · 当前仅手动触发'}}</span></div>
    <nav><button v-for="item in [{id:'experiments',label:'策略实验'},{id:'claude',label:'Claude 交互研究'},{id:'settings',label:'验证配置'},{id:'guide',label:'操作指引'}]" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{item.label}}</button></nav>
    <p v-if="error" class="banner error" role="alert">{{error}}</p><p v-if="notice" class="banner success">{{notice}}</p>
    <p v-if="busy" class="banner" role="status">{{busy==='discover'?'Claude 正在提出策略假设…':busy==='start'?'正在筛选标的、检查历史并准备模拟账户…':'正在处理…'}}<button v-if="busy==='discover'" @click="invoke('cancel_agent_analysis')">中止 AI</button></p>
    <section v-if="tab==='experiments'">
      <div class="toolbar"><p>同一规则与参数只登记一次，失败记录也会保留。</p><button @click="load()" :disabled="!!busy">刷新</button><button class="primary" :disabled="!!busy||dashboard?.busy||!dashboard?.agent_installed" @click="discover">＋ AI 研究新候选</button></div>
      <p v-if="dashboard?.last_auto_message" class="last-auto">{{dashboard.last_auto_message}}</p>
      <div v-if="!counts.all" class="empty"><span>01</span><h3>从一条可检验的假设开始</h3><p>先在“验证配置”中设定考核条件，再让 AI 生成候选，或打开 Claude 使用你的 Skill 研究。</p><button class="primary" @click="tab='settings'">设置验证条件</button></div>
      <div v-else class="workspace">
        <aside><button v-for="item in dashboard?.experiments" :key="item.id" class="experiment" :class="{selected:item.id===selectedId}" @click="selectedId=item.id"><span class="badge" :data-state="item.state">{{states[item.state]||item.state}}</span><strong>{{item.name}}</strong><small>{{rules[item.rule]}} · 版本 #{{item.version_id}}</small><span>{{pct(item.detail?.metrics.total_return_bps)}}<small>收益</small>　{{pct(item.detail?.metrics.max_drawdown_bps)}}<small>回撤</small></span></button></aside>
        <article v-if="selected" class="detail">
          <div class="detail-title"><div><span class="eyebrow">EXPERIMENT {{selected.id}} / VERSION {{selected.version_id}}</span><h3>{{selected.name}}</h3></div><span class="badge" :data-state="selected.state">{{states[selected.state]}}</span></div>
          <p class="hypothesis">{{selected.hypothesis}}</p>
          <div class="limits"><span>观察 {{selected.config.observation_days}} 天</span><span>至少 {{selected.config.min_samples}} 笔卖出</span><span>最大回撤 {{pct(selected.config.max_drawdown_bps)}}</span><span>收益超过 {{pct(selected.config.min_return_bps)}} 且跑赢基准</span></div>
          <p class="next-step">{{selected.last_message||'下一步：自动选股并启动前向模拟。研究实验不会绕过原有实战准入门禁。'}}</p>
          <div class="actions"><button v-if="selected.state==='candidate'" class="primary" :disabled="!!busy||!dashboard?.local_ready" @click="start">自动选股并启动验证</button><button v-if="['observing','extended','adopted'].includes(selected.state)" :disabled="!!busy" @click="action('run')">立即推进</button><button v-if="['observing','extended','adopted'].includes(selected.state)" :disabled="!!busy" @click="action('pause')">暂停</button><button v-if="selected.state==='paused'" :disabled="!!busy" @click="action('resume')">恢复原实验</button><button v-if="selected.state==='qualified'" class="primary" :disabled="!!busy" @click="action('adopt')">采纳为研究策略并继续跟踪</button><button v-if="selected.state!=='rejected'" :disabled="!!busy" @click="action('reject')">淘汰并保留记录</button></div>
          <template v-if="selected.detail">
            <p class="next-step" v-if="live">{{live.message}}<small> · {{live.engine==='realtime_a_share'?'A 股实时前向':'日线前向对照'}} · 已观测 {{live.marks}} 个行情分钟</small></p>
            <div v-if="live?.plans.length" class="table-wrap"><table><thead><tr><th>实时买卖计划</th><th>买入区间</th><th>止损触发</th><th>止盈卖点</th></tr></thead><tbody><tr v-for="p in live.plans" :key="p.symbol"><td>{{p.symbol}}</td><td>{{(p.buy_low/10000).toFixed(2)}}–{{(p.buy_high/10000).toFixed(2)}}</td><td>{{(p.stop/10000).toFixed(2)}}</td><td>{{(p.take/10000).toFixed(2)}}</td></tr></tbody></table></div>
            <details v-if="live?.executions.length"><summary>查看实时成交证据：时间、对手盘、数量与费用</summary><pre>{{JSON.stringify(live.executions,null,2)}}</pre></details>
            <div v-if="daily" class="table-wrap"><h4>并行对照 · 资金和订单完全独立，主考核依据实时账户</h4><table><thead><tr><th>执行口径</th><th>收益</th><th>最大回撤</th><th>完成卖出</th></tr></thead><tbody><tr><td>实时 · 新盘口成交</td><td>{{pct(selected.detail.metrics.total_return_bps)}}</td><td>{{pct(selected.detail.metrics.max_drawdown_bps)}}</td><td>{{selected.detail.metrics.sample_count}}</td></tr><tr><td>日线 · 次日开盘假设</td><td>{{pct(daily.metrics.total_return_bps)}}</td><td>{{pct(daily.metrics.max_drawdown_bps)}}</td><td>{{daily.metrics.sample_count}}</td></tr></tbody></table><p class="note">这是两种执行方式的结果对照。买卖时机与触发规则可能不同，差额不能全部归因于滑点。</p></div>
            <div class="metrics"><div><small>账户权益</small><b>¥{{money(selected.detail.metrics.equity)}}</b></div><div><small>累计收益</small><b>{{pct(selected.detail.metrics.total_return_bps)}}</b></div><div><small>最大回撤</small><b>{{pct(selected.detail.metrics.max_drawdown_bps)}}</b></div><div><small>同期基准</small><b>{{pct(selected.detail.metrics.benchmark_return_bps)}}</b></div></div>
            <div class="progress-row"><div><label>时间 · 已记录 {{selected.elapsed_days}} 天 / 还需 {{selected.remaining_days}} 天</label><progress :value="selected.elapsed_days" :max="selected.config.observation_days" /></div><div><label>样本 · {{selected.detail.metrics.sample_count}} 笔 / 还需 {{selected.remaining_samples}} 笔</label><progress :value="selected.detail.metrics.sample_count" :max="selected.config.min_samples" /></div></div>
            <div class="chart"><h4>账户收益曲线 <small>日终概览 · 实时账户回撤按已观测盘中净值计算</small></h4><svg v-if="selected.curve.length" viewBox="0 0 720 185" role="img" aria-label="账户累计收益曲线"><line x1="40" :y1="chart.zero" x2="690" :y2="chart.zero" stroke="currentColor" opacity=".2" stroke-dasharray="4 4"/><polyline :points="chart.points" fill="none" stroke="var(--color-accent)" stroke-width="2.5"/><text x="3" y="25" fill="currentColor" font-size="11">{{pct(chart.high)}}</text><text x="3" y="155" fill="currentColor" font-size="11">{{pct(chart.low)}}</text><text x="40" y="180" fill="currentColor" font-size="11">初始资金</text><text x="590" y="180" fill="currentColor" font-size="11">{{selected.curve.at(-1)?.date}}</text></svg><p v-else>等待首次有效净值记录。没有数据时不绘制虚假曲线。</p></div>
            <h4>冻结股票池 · 模拟账户 #{{selected.account_id}}</h4><div class="targets"><span v-for="stock in selected.detail.targets" :key="stock.symbol">{{stock.name}} <small>{{stock.symbol}}</small></span></div>
            <h4>最近模拟指令</h4><div class="table-wrap"><table><thead><tr><th>信号日</th><th>标的</th><th>方向</th><th>股数</th><th>状态 / 原因</th></tr></thead><tbody><tr v-for="order in selected.detail.orders.slice(0,20)" :key="order.id"><td>{{order.signal_date}}</td><td>{{order.symbol}}</td><td>{{order.side==='buy'?'买入':'卖出'}}</td><td>{{order.quantity}}</td><td>{{order.status}} {{order.reject_reason}}</td></tr><tr v-if="!selected.detail.orders.length"><td colspan="5">尚未触发规则；自动运行不代表必须交易。</td></tr></tbody></table></div>
          </template>
          <details><summary>查看冻结条件和选股依据</summary><pre>{{JSON.stringify({rule:selected.rule,filter:selected.filter,selection:JSON.parse(selected.selection_json)},null,2)}}</pre></details>
        </article>
      </div>
    </section>
    <section v-else-if="tab==='claude'" class="reading">
      <h3>像平时一样，与 Claude 一起研究</h3><p>这个入口打开真实终端中的交互会话，保留本机个人 Skill 的发现机制。你可以点名 Skill、追问证据、让它查资料并写研究笔记。权限提示由 Claude 的默认交互模式处理。</p>
      <div class="flow-cards"><div><b>1. 打开会话</b><p>进入专用研究目录，读取应用提供的研究任务书。</p></div><div><b>2. 选择 Skill 研究</b><p>让 Claude 说明实际用了哪些资料、方法及缺失项。</p></div><div><b>3. 导入候选</b><p>Claude 写出 candidate.json，应用严格校验后登记。</p></div></div>
      <div class="actions"><button class="primary" :disabled="!!busy||!dashboard?.agent_installed" @click="openClaude">打开 Claude 研究窗口</button><button :disabled="!!busy" @click="inspectWorkspace">查看研究任务书与个人 Skill</button><button :disabled="!!busy" @click="importCandidate">导入 candidate.json</button></div>
      <div v-if="workspace"><p class="path">专用目录：{{workspace.path}}</p><p>发现的个人 Skill：{{workspace.skills.join('、')||'未在 ~/.claude/skills 中发现；插件 Skill 请在 Claude 窗口中查看'}}</p><details><summary>实际研究任务书</summary><pre>{{workspace.prompt}}</pre></details></div>
      <p class="note">交互会话由你管理，关闭研究中心不会结束它。只有点击“导入”才会写入候选库，Claude 不直接写模拟账本。自动后台任务仍采用受限方法。</p>
    </section>
    <section v-else-if="tab==='settings'" class="reading">
      <h3>先写清考核条件，再开始实验</h3><p>这些数值会随新候选冻结。已有实验不会随设置变动，避免边测试边改答案。</p>
      <label>模拟执行方式 <select v-model="executionMode" style="padding:8px;background:var(--color-surface-2);color:var(--color-text-primary)"><option value="realtime">实时前向（默认）：未来新盘口触发与成交</option><option value="parallel">并行对照：实时主账户 ＋ 独立日线账户</option><option value="daily">日线前向：日线信号，下一交易日开盘价</option></select></label>
      <div class="config-grid"><label>观察期（自然日，按有效行情进度）<input v-model.number="settings.observation_days" type="number" min="7" max="365"/></label><label>最少完成卖出样本<input v-model.number="settings.min_samples" type="number" min="5" max="500"/></label><label>回撤上限（%）<input v-model.number="drawdownPct" type="number" min="1" max="50"/></label><label>最低累计收益（%，还须跑赢基准）<input v-model.number="returnPct" type="number" min="0" max="100"/></label><label>每账户初始资金（元）<input v-model.number="cashYuan" type="number" min="1000"/></label><label>每次冻结股票数<input v-model.number="settings.stock_count" type="number" min="1" max="10"/></label><label>同时候选 / 验证上限<input v-model.number="settings.max_active" type="number" min="1" max="5"/></label><label>佣金（基点）<input v-model.number="settings.commission_bps" type="number" min="0" max="1000"/></label><label>最低佣金（元）<input v-model.number="minFee" type="number" min="0"/></label><label>卖出印花税（基点）<input v-model.number="settings.stamp_tax_bps" type="number" min="0" max="1000"/></label><label>过户费（基点）<input v-model.number="settings.transfer_fee_bps" type="number" min="0" max="1000"/></label><label>滑点（基点）<input v-model.number="settings.slippage_bps" type="number" min="0" max="1000"/></label></div>
      <label class="auto-toggle"><input v-model="settings.auto_research" type="checkbox"/><span><b>启用盘后自动研究与启动验证</b><small>交易日 16:00–22:00 每天最多一次：优先启动待处理候选，否则让 AI 提出新候选；自动选股并启动模拟。默认关闭，失败当日不自动重试，关闭不暂停已有模拟账户。</small></span></label>
      <button class="primary" :disabled="!!busy" @click="save">保存新实验的默认配置</button>
    </section>
    <section v-else class="reading"><h3>推荐操作流程</h3><ol class="guide"><li><b>准备数据</b><p>设置 → 行情，启用本地历史引擎，更新前复权及未复权日线；设置 → 智能，测试 Claude 连接。</p></li><li><b>设定考核</b><p>在验证配置中固定资金、费用、观察期、样本数与回撤限制。先从一个实验开始。</p></li><li><b>提出候选</b><p>选择“AI 研究新候选”，或打开 Claude 窗口调用自己的 Skill 后导入 candidate.json。</p></li><li><b>自动选股并启动</b><p>程序按条件筛选沪深主板，排除 ST 等标的，按成交额取前几只并冻结。账户执行已有确定性规则，AI 不直接下单。</p></li><li><b>每天更新与观察</b><p>实时模式保持应用运行与网络畅通，连续竞价时段按新鲜盘口执行，遵守 T+1；日线模式盘后更新本地数据，按下一交易日开盘价推进。并行模式两边独立统计，断线期间不补算实时成交。</p></li><li><b>等时间与样本说话</b><p>时间不到不判通过；样本或基准缺失则延长；超过回撤上限或考核不通过则淘汰。达到门槛后人工采纳为研究策略，并继续模拟跟踪。</p></li></ol><p class="note">当前实验使用一次冻结股票池及三种现有交易规则。后续轮动选股、任意新算法、完整历史组合验证仍需进一步建设。实验通过不等于实盘盈利或原有实战门禁通过。</p></section>
